value:
%_rw:3;
%_cl:5;
matP:random_matrix_det_list(3, [-2, -1, -1, -1, -1, 0, 1, 1, 1, 1, 2], [-1, 1]);
pv:rand([[1, 2], [1, 3], [1, 2, 3], [1, 2, 4]]);
matF:randechelon(3, 5, pv, [-2, -1, 1, 2]);
matA:matP.matF;
nL:nullspace2(matF);
taD:length(nL);/* or 5-length(pv) */
while length(nL)<7 do nL:endcons(EMPTYANSWER, nL);
ta1:nL[1];
ta2:nL[2];
ta3:nL[3];
ta4:nL[4];
ta5:nL[5];
ta6:nL[6];
BASE:%__lang([["ja", "基底"], ["en", "Basis"]]);
DIM:%__lang([["ja", "次元"], ["en", "Dim"]]);
%_validate(ansL):=block([k, ret], ret:true,
  for k:1 thru 6 do ret:ret and (ansL[k]=EMPTYANSWER or is(matrix_size(ansL[k])=[%_cl, 1])), return(ret));
/* length must be %_Num_Nodes */
%_chkfunc(ansL):=[false, true, true, false, false, true, false, true];

{"baseLanguage": "ja", "languages": ["ja", "en"], "libraryIncludes": {"ky_linear_algebra": "https://yositomi-opu.github.io/stack_questions/ky_linear_algebra.mac", "multilang_library": "https://yositomi-opu.github.io/stack_questions/multilang_library.mac"}, "questionMessages": {"ja": "行列\(A=\){@matA@}に対して, 解空間\(A{@Wx@}=\boldsymbol0\)の基底と次元を求めよ. 基底の解答欄については, 不要な欄は空欄にすること.", "en": "For the matrix \(A=\){@matA@}, find a basis and the dimension of the solution space \(A{@Wx@}=\boldsymbol0\). In the answer fields for the basis, leave any unnecessary fields blank."}, "questionEnabled": true, "questionVariable": "qtext", "feedbackVariables": "ansL:[ans1, ans2, ans3, ans4, ans5, ans6, ansD];
chkV:%_validate(ansL);
if chkV then chkL:%_chkfunc(ansL) else chkL:makelist(false,%_Num_Nodes+1);
sc:0;
if chkV then for k:1 thru %_Num_Nodes do if chkL[k+1] then sc:sc+scL[k];
"}
